function stopGestureMode() {
  gestureSession?.stop?.();
  gestureSession = null;
  setCameraStatus("idle");
}

function handleGestureAction(gesture) {
  if (gesture !== "PINCH" || !state.detail.isOpen) {
    return;
  }

  state = reduceAppState(state, { type: "detail/close" });
